class a{archiveBaseUrl="/events-archive";async createArchiveFile(e){return{success:!1,fileName:"",error:"La migración se gestiona automáticamente vía GitHub Actions cada 1 de enero."}}async archiveExists(e){try{const r=await fetch(`${this.archiveBaseUrl}/${e}.json`);if(!r.ok)return!1;const c=r.headers.get("content-type");return!(c&&c.includes("text/html"))}catch{return!1}}async getArchiveData(e){try{console.log(`[StaticFileService] Cargando datos de ${e}...`);const r=await fetch(`${this.archiveBaseUrl}/${e}.json`);if(!r.ok)return console.warn(`[StaticFileService] No se encontró el archivo de ${e}`),null;const c=r.headers.get("content-type");if(c&&c.includes("text/html"))return console.warn(`[StaticFileService] El archivo de ${e} devolvió HTML (404 reescrito)`),null;const t=await r.json();return console.log(`[StaticFileService] ✅ ${e} cargado con ${t.events?.length||0} eventos.`),t}catch(r){return console.error(`[StaticFileService] Error al cargar ${e}:`,r),null}}async getAvailableYears(){try{const e=await fetch(`${this.archiveBaseUrl}/index.json`);if(e.ok){const t=e.headers.get("content-type");if(t&&!t.includes("text/html")){const n=await e.json();return console.log("[StaticFileService] Índice cargado:",n.years),n.years||[]}}console.log("[StaticFileService] Índice no encontrado o inválido, buscando manualmente...");const r=new Date().getFullYear(),c=[];for(let t=2024;t<r;t++)await this.archiveExists(t)&&c.push(t);return console.log("[StaticFileService] Años encontrados manualmente:",c),c.sort((t,n)=>n-t)}catch(e){return console.error("[StaticFileService] Error al obtener años:",e),[]}}}const s=new a;export{s as default,s as staticFileService};
